return `${pageHeader(p.id==='new'?'添加供应商':p.name,'配置保存在应用层，项目和会话按需选择模型。',btn('返回','nav-models','ghost','back'))}<div class="form-grid">${field('显示名称','provider-name',p.name)}${field('协议','provider-protocol',p.protocol,'','select',protocols.map(protocol=>`<option ${p.protocol===protocol?'selected':''}>${protocol}</option>`).join(''))}</div>${field('接口地址','provider-endpoint',p.endpoint,'请使用完整的服务基础地址。地址修改不会自动改变协议。')}${field('API Key','provider-key','','原型不保存此字段；正式实现使用 Windows 安全存储。','password')}<div class="section-heading"><h3>模型目录</h3><div class="flex">${btn('获取模型列表','fetch-models','sm','refresh')}${btn('手动添加','model-add','sm','plus')}</div></div><div class="list">${models.map(m=>`<div class="list-row" style="padding:12px 0"><div class="grow"><h3>${esc(m.name)}</h3><p class="mono">${esc(m.wire)}</p></div><span class="small muted">${esc(m.media)}</span><button class="icon-btn" data-model-edit="${m.id}" aria-label="编辑模型能力">${icon('chevron')}</button></div>`).join('')||'<div class="empty-state">此供应商尚未添加模型。</div>'}</div><details class="tool" style="margin-top:20px"><summary>${icon('settings')}<span>高级参数、请求头与自定义模板</span>${icon('chevron','chevron')}</summary><div class="tool-body"><div class="form-grid">${field('附加请求头','provider-headers','{}','无密钥导出也排除附加请求头。','textarea')}${field('自定义请求模板','provider-template','{
    "model": "{{model}}",
    "messages": "{{messages}}"
}','仅用于自定义模板协议；UI 不自动注入未声明的能力。','textarea')}</div></div></details><div class="between" style="margin-top:22px"><div class="flex">${btn('测试连接','test-provider','','plug')}<span class="small muted" data-copy-scope="mixed" data-copy-action="split">仅模拟测试，不产生 API 费用</span></div>${S.transientResult?pill(esc(S.transientResult),'good'):''}</div><div class="form-actions">${p.id!=='new'?btn('删除供应商','delete-provider','danger left','trash'):''}${btn('取消','nav-models')}${btn('保存配置','save-provider','primary')}</div>`;

return `${pageHeader('Vue 组件规范','SKILL.md · 来源：Vue 开发规范',btn('返回 Skills','nav-skills','ghost','back'))}<div class="subtle-box"><div class="between"><span class="mono small">vue-component / SKILL.md</span>${pill('只读预览')}</div></div><article class="prose" style="margin:30px 0"><h2>编写清晰、可维护的 Vue 组件</h2><p>当任务涉及 Vue 页面、组件或相关状态逻辑时，先阅读现有项目规范，再应用这些约定。</p><h3>语言与格式</h3><p>业务页面和业务组件使用 JavaScript；稳定复用模块使用 TypeScript。统一使用四空格缩进，修改旧代码时保持同一文件风格一致。</p><h3>异步交互</h3><p>用户触发的异步动作具有 loading 锁。明确展示失败状态，结束 loading 后再显示提示，不让重复点击产生并发提交。</p><pre><code>if (loading.value) return;
loading.value = true;
request().then(handleResult).catch(handleError)
    .finally(() =&gt; { loading.value = false; });</code></pre><blockquote>这是技能内容的排版示例，不替代仓库中的真实 SKILL.md。</blockquote><h3>关联资源</h3><div class="flex">${btn('references / components.md','skill-reference','sm','file')}${btn('查看来源插件','skill-parent','sm','puzzle')}</div></article>`;
